<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presensi Berhasil</title><style>*{box-sizing:border-box}body{margin:0;background:#f1f7f4;color:#173d31;font:15px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif;display:grid;min-height:100vh;place-items:center}.card{width:min(100% - 30px,480px);background:#fff;border:1px solid #dce9e3;border-radius:22px;padding:30px;text-align:center;box-shadow:0 12px 38px #084c3318}.icon{width:76px;height:76px;border-radius:50%;display:grid;place-items:center;margin:0 auto 18px;background:#daf3e7;color:#08704e;font-size:42px}.card h1{font-size:23px;margin:0 0 8px}.event{background:#f3f8f5;border-radius:13px;padding:15px;margin:20px 0;text-align:left}.event strong,.event span{display:block}.event span{font-size:13px;color:#66786f;margin-top:5px}.code{font-size:12px;color:#718078}.note{font-size:13px;color:#5e7067}</style></head><body><main class="card"><div class="icon">✓</div><h1>{{ $receipt['duplicate'] ? 'Sudah Tercatat' : 'Presensi Berhasil' }}</h1><p>{{ $receipt['duplicate'] ? 'Kehadiran Anda sebelumnya sudah tercatat.' : 'Terima kasih, kehadiran Anda berhasil disimpan.' }}</p><div class="event"><strong>{{ $receipt['name'] }}</strong><span>{{ $receipt['event'] }}</span><span>{{ $receipt['attended_at'] }}</span></div><div class="code">Kode konfirmasi: {{ $code }}</div><p class="note">Anda boleh menutup halaman ini.</p></main></body></html>
